import type { VariableConfig } from '../../Variable';
/**
 * Configuration type for numeric scale variables
 */
export type NumericScaleVariableType<Type extends number = number> = VariableConfig<Type> & {
    /** Minimum value for the scale */
    scaleMin?: number;
    /** Maximum value for the scale */
    scaleMax?: number;
    /** Whether to select the first choice */
    doNotSelectFirstChoice?: boolean;
};
/**
 * A Variable for a numeric scale field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the numeric scale variable including:
 *   * **question** - Question text displayed to the user
 *   * **min**? - Minimum value for the scale (defaults to 0)
 *   * **max**? - Maximum value for the scale (defaults to 10)
 *   * **doNotSelectFirstChoice**? - Whether to select the first choice (defaults to false)
 *   * **defaultValue**? - Default value for the variable
 *   * And all other properties from the base Variable type
 */
export declare function NumericScaleVariable(config: NumericScaleVariableType): NumericScaleVariableType<number>;
